// Node Redis operasi "keys" TIDAK mengembalikan properti `keys`.
// Bentuk keluarannya bergantung versi/opsi: {"queue_a.com":"a.com"} atau {"queue_*":[...]}.
// Fungsi ini menerima semua bentuk itu dan mengembalikan Set nama key.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

// 1) key antrean yang sudah ada di Redis
const queued = collectKeys($('Redis Get: queue').all(), 'queue_');

// 2) domain yang SUDAH dianalisis AI (ada di dns_info) tidak perlu diantre lagi
const known = new Set();
try {
  for (const it of $('Mongodb: Find document (dns_info)').all()) {
    const dom = String((it.json || {}).domain || '').toLowerCase().trim();
    if (dom) known.add(dom);
  }
} catch (e) {}

const nowIso = new Date().toISOString();
const seenInBatch = new Set();
const out = [];

// SEMUA baris diteruskan. `onQueue` hanya menentukan apakah domain perlu masuk
// antrean analisis AI; pengecekan blacklist & pencatatan akses berlaku untuk semua baris.
for (const row of $('Split Out (per domain)').all()) {
  const data = row.json || {};
  const domain = String(data.domain || '').toLowerCase().trim().replace(/\.$/, '');
  if (!domain) continue;

  const needsQueue = !known.has(domain) && !queued.has('queue_' + domain) && !seenInBatch.has(domain);
  if (needsQueue) seenInBatch.add(domain);

  out.push({ json: { ...data, domain, timestamp: nowIso, onQueue: !needsQueue } });
}
return out;

// Node Redis operasi "keys" TIDAK mengembalikan properti `keys`.
// Bentuk keluarannya bergantung versi/opsi: {"queue_a.com":"a.com"} atau {"queue_*":[...]}.
// Fungsi ini menerima semua bentuk itu dan mengembalikan Set nama key.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

const rows = $('Filter Set as queue (Code - JS)').all().map(i => i.json);

// ---- blacklist (hanya entri aktif & belum kedaluwarsa; is_active kosong dianggap aktif)
let docs = [];
try {
  docs = $('Mongodb: Find document (dns_blacklist)').all()
    .map(i => i.json || {})
    .filter(x => String(x.domain || '').trim() !== '' || (x.blocked_level === 'group' && String(x.group || '').trim() !== ''));
} catch (e) {}
const source = docs;  // blacklist murni dari koleksi dns_blacklist (tidak ada daftar tersembunyi di workflow)
const nowMs = Date.now();
// Entri level "group" (tanpa domain) dicocokkan lewat group hasil klasifikasi di dns_info, sama seperti backend.
// Set false untuk kembali ke perilaku lama (entri group diabaikan).
const MATCH_GROUP_ENTRIES = true;
const blocked = new Map();
const groupBlocked = new Map();
for (const b of source) {
  if (b.is_active === false) continue;
  if (b.expires_at && new Date(b.expires_at).getTime() < nowMs) continue;  // entri feed kedaluwarsa
  if (b.blocked_level === 'group' && String(b.domain || '').trim() === '') {
    if (MATCH_GROUP_ENTRIES) groupBlocked.set(String(b.group).trim().toLowerCase(), b);
    continue;
  }
  blocked.set(String(b.domain).toLowerCase().trim(), b);
}
// cocokkan domain itu sendiri dan induknya: a.b.slot.com -> b.slot.com -> slot.com
function matchBlacklist(domain) {
  const labels = domain.split('.');
  for (let i = 0; i < labels.length - 1; i++) {
    const hit = blocked.get(labels.slice(i).join('.'));
    if (hit) return hit;
  }
  // tidak ada entri domain: coba entri group lewat klasifikasi domain ini
  if (groupBlocked.size) {
    const k = info.get(domain);
    const g = k && String(k.group || '').trim().toLowerCase();
    if (g && groupBlocked.has(g)) return groupBlocked.get(g);
  }
  return null;
}

// ---- hasil analisis AI (untuk group/type domain yang tidak diblacklist)
const info = new Map();
try {
  for (const it of $('Mongodb: Find document (dns_info)').all()) {
    const x = it.json || {};
    if (x.domain) info.set(String(x.domain).toLowerCase(), x);
  }
} catch (e) {}

// ---- notifikasi yang sudah terkirim (dedupe per domain+client)
let notified = new Set();
try { notified = collectKeys($('Redis Keys: dns_notification').all(), 'dns_notification_'); } catch (e) {}

// ---- domain yang sudah pernah dikirim ke SLACK (dedupe 24 jam, terpisah dari dedupe backend)
let slackSent = new Set();
try { slackSent = collectKeys($('Redis Keys: slack_sent').all(), 'slack_sent_'); } catch (e) {}
let slackPending = new Set();
try { slackPending = collectKeys($('Redis Keys: slack_pending').all(), 'slack_pending_'); } catch (e) {}

// ---- satu baris log per (client, domain, AP) per batch
const grouped = new Map();
for (const r of rows) {
  const key = [r.client_ip, r.domain, r.ap_ip].join('|');
  const g = grouped.get(key) || { ...r, access_count: 0 };
  g.access_count += 1;
  grouped.set(key, g);
}

const out = [];
for (const g of grouped.values()) {
  const bl = matchBlacklist(g.domain);
  const known = info.get(g.domain);
  const client_ip = g.client_ip || '';
  // Mode entri blocklist: kosong = 'alert' (hanya dipantau). enforced = benar-benar diblokir di DNS:
  // mode 'enforce' DAN aturan sudah tersinkron ke AdGuard (enforce_status 'synced').
  const block_mode = bl ? (bl.block_mode === 'enforce' ? 'enforce' : 'alert') : '';
  const enforced = block_mode === 'enforce' && bl.enforce_status === 'synced';
  out.push({
    json: {
      timestamp: g.timestamp,
      domain: g.domain,
      client_ip,
      ap_ip: g.ap_ip || '',
      ap_name: g.ap_name || '',
      ap_info: { label: g.ap_name || '', ip: g.ap_ip || '' },
      group: bl ? (bl.group || 'Ilegal') : ((known && known.group) || 'Unknown'),
      type: bl ? (bl.type || 'blacklist') : ((known && known.type) || 'unknown'),
      // action 'blocked' = cocok blocklist (tetap, demi kompatibilitas). Gunakan enforced untuk 'benar-benar diblokir'.
      action: bl ? 'blocked' : 'allowed',
      block_mode,
      enforced,
      access_count: g.access_count,
      description: (bl && bl.description) || '',
      inBlacklist: !!bl,
      detected: !!bl,
      // notify = perlu kirim alert (kena blacklist DAN belum diberi tahu dalam 20 menit terakhir)
      notify: !!bl && !notified.has('dns_notification_' + g.domain + '_' + client_ip),
      // notify_slack = kena blacklist, belum dikirim ke Slack (24 jam) DAN belum menunggu di antrean Slack
      notify_slack: !!bl && !slackSent.has('slack_sent_' + g.domain + '_' + client_ip) && !slackPending.has('slack_pending_' + g.domain + '_' + client_ip),
      query_type: g.query_type || '',
      source_type: g.source_type || 'mikrotik_dns',
    },
  });
}
return out;

