const VALID = new Set(['social_media','streaming','gaming','gambling','adult','cloud','cdn','educational','other']);
const lookups = $('Lookup: Build').all().map(i => i.json);
const batches = $('AI: Build Batches').all().map(i => i.json);
const inputs = $input.all().map(i => i.json);
const requested = new Set(batches.flatMap(b => b.domains || []));
const nowIso = new Date().toISOString();
const str = v => (typeof v === 'string' ? v.trim() : '');
const arrStr = v => (Array.isArray(v) ? v.map(str).filter(Boolean) : []);

const ai = new Map();   // domain induk -> { group, type, info_app }
let failedBatches = 0, aiBatches = 0, skipped = 0;
for (const r of inputs) {
  if (r.skip_ai) continue;
  aiBatches++;
  if (r.error || !r.candidates) { failedBatches++; continue; }
  const parts = ((((r.candidates || [])[0] || {}).content || {}).parts) || [];
  const text = parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('').replace(/```json|```/g, '').trim();
  let parsed = [];
  try { parsed = JSON.parse(text); } catch (e) { failedBatches++; continue; }
  if (!Array.isArray(parsed)) parsed = (parsed && typeof parsed === 'object') ? [parsed] : [];
  for (const p of parsed) {
    const domain = str(p && p.domain).toLowerCase().replace(/\.$/, '');
    const type = str(p && p.type).toLowerCase();
    if (!domain || !VALID.has(type)) { skipped++; continue; }          // N4: tolak entri tanpa domain / type valid
    if (!requested.has(domain)) { skipped++; continue; }                 // abaikan domain yang tidak diminta
    const ia = (p.info_app && typeof p.info_app === 'object') ? p.info_app : {};
    ai.set(domain, { group: str(p.group) || 'Unknown', type, info_app: {
      platform: arrStr(ia.platform), company_responsible: str(ia.company_responsible), owner: str(ia.owner) } });
  }
}
// Semua batch gagal -> berhenti dengan error (ditangkap Error Handler). Antrean tidak dihapus.
if (aiBatches > 0 && failedBatches === aiBatches) throw new Error('AI Analyzer gagal untuk semua batch (' + aiBatches + '). Antrean dipertahankan.');

const out = [];
for (const l of lookups) {
  const cls = l.cached || ai.get(l.domain) || ai.get(l.reg);
  if (!cls) continue;     // belum terklasifikasi: tetap di antrean untuk siklus berikutnya
  out.push({ json: {
    domain: l.domain, group: cls.group, type: cls.type, info_app: cls.info_app,
    ip_scan: l.ip_scan || [], ptr_hostname: l.ptr_hostname || '', host_isp: l.host_isp || {},
    last_verified: nowIso, timestamp: nowIso, ai_ok: true,
    classified_at: l.cached ? (l.cached.classified_at || nowIso) : nowIso,
    source: l.cached ? 'cache' : 'ai',
    network_source: l.net_ok ? 'lookup' : 'none',
    _queue_domain: l.queue_domain || '',
  } });
}
return out;

// Node Redis operasi "keys" TIDAK mengembalikan properti `keys`.
// Bentuk keluarannya bergantung versi/opsi: {"queue_a.com":"a.com"} atau {"queue_*":[...]}.
// Fungsi ini menerima semua bentuk itu dan mengembalikan Set nama key.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

// Batasi per jalan agar balasan Gemini tidak terpotong. Sisanya diproses pada Cron berikutnya.
const MAX_PER_RUN = 100;  // batas domain per siklus (diproses 20 per request AI)

const keys = [...collectKeys($input.all(), 'queue_')].sort();

// Antrean kosong itu normal: workflow berhenti di sini tanpa error.
return keys.slice(0, MAX_PER_RUN).map(key => ({ json: { key } }));

// Gabungkan SEMUA domain yang menunggu (dari banyak batch webhook) menjadi
// SATU pesan per client, dikelompokkan per group. Maks MAX_PER_GROUP domain tampil per group.
// Pesan membedakan domain yang benar-benar DIBLOKIR di DNS (mode enforce, AdGuard) dari yang hanya terpantau.
const MAX_PER_GROUP = 10;
const byClient = new Map();
const seen = new Set();

for (const it of $input.all()) {
  let r = it.json.value;
  try { if (typeof r === 'string') r = JSON.parse(r); } catch (e) { continue; }
  if (!r || !r.domain || !r.client_ip) continue;

  const uniq = r.client_ip + '|' + r.domain;
  if (seen.has(uniq)) continue;
  seen.add(uniq);

  const enforced = r.enforced === true;
  const c = byClient.get(r.client_ip) || { client_ip: r.client_ip, aps: new Set(), groups: new Map(), entries: [], blocked: 0 };
  if (r.ap_name) c.aps.add(r.ap_name);
  const list = c.groups.get(r.group || 'Unknown') || [];
  list.push({ domain: r.domain, enforced });
  c.groups.set(r.group || 'Unknown', list);
  c.entries.push({ domain: r.domain, client_ip: r.client_ip, enforced });
  if (enforced) c.blocked++;
  byClient.set(r.client_ip, c);
}

return [...byClient.values()].map(c => {
  const total = c.entries.length;
  const monitored = total - c.blocked;
  const head = c.blocked === total
    ? ':shield: *Blacklist Alert \u2014 DIBLOKIR (DNS)*'
    : c.blocked === 0
      ? ':warning: *Blacklist Alert \u2014 terpantau (tidak diblokir)*'
      : ':warning: *Blacklist Alert*';
  let text = `${head}\nClient \`${c.client_ip}\` | AP: *${[...c.aps].join(', ') || '-'}* | ${total} domain baru`;
  if (c.blocked > 0 && monitored > 0) text += `\nDIBLOKIR (DNS): ${c.blocked} | Terpantau (tidak diblokir): ${monitored}`;
  for (const [group, domains] of c.groups) {
    text += `\n\n*${group}* (${domains.length})`;
    domains.slice(0, MAX_PER_GROUP).forEach(x => { text += `\n\u2022 \`${x.domain}\`${x.enforced ? ' \u2014 diblokir' : ''}`; });
    if (domains.length > MAX_PER_GROUP) {
      text += `\n\u2022 \u2026dan ${domains.length - MAX_PER_GROUP} domain lainnya (lihat dashboard)`;
    }
  }
  return { json: { origin: 'blacklist', severity: 'warning', title: '', text, data: { client_ip: c.client_ip, total, blocked: c.blocked, entries: c.entries } } };
});

// Node Redis operasi "keys" bentuk keluarannya bervariasi; fungsi ini menerima semua bentuk.
function collectKeys(items, prefix) {
  const out = new Set();
  const add = (v) => { if (typeof v === 'string' && v.startsWith(prefix) && !v.includes('*')) out.add(v); };
  for (const it of items) {
    const j = (it && it.json) || {};
    for (const [prop, val] of Object.entries(j)) {
      add(prop);
      if (Array.isArray(val)) val.forEach(add); else add(val);
    }
  }
  return out;
}

const pending = collectKeys($('Flush: Redis Keys pending').all(), 'slack_pending_');
const sent = collectKeys($('Flush: Redis Keys sent').all(), 'slack_sent_');

// Lewati entri yang ternyata sudah terkirim (mencegah dobel karena race antar eksekusi)
const keys = [...pending].sort().filter(k => !sent.has('slack_sent_' + k.slice('slack_pending_'.length)));

// Antrean kosong itu normal: workflow berhenti di sini tanpa error.
return keys.map(key => ({ json: { key } }));

// Jalan hanya untuk notifikasi yang BERHASIL (minimal satu kanal ok, atau dilewati jam tenang/severity).
// Pecah kembali jadi satu item per (domain, client) untuk ditandai terkirim dan dihapus dari antrean.
const out = [];
for (const it of $input.all()) {
  const data = (it.json && it.json.data) || {};
  for (const e of (data.entries || [])) out.push({ json: e });
}
return out;

// Simpan payload webhook apa adanya (data mentah) untuk arsip jangka panjang.
const body = $input.first().json.body;
const now = new Date();
const wibDate = new Date(now.getTime() + 7 * 3600 * 1000).toISOString().slice(0, 10);
return [{ json: {
  received_at: now.toISOString(),
  date: wibDate,
  source: 'webhook:dns-scan-webhook',
  row_count: Array.isArray(body) ? body.length : (body ? 1 : 0),
  payload: body === undefined ? null : body,
} }];

// ===== Konfigurasi =====
const TZ_OFFSET_MIN = 7 * 60;  // WIB = UTC+7
const HIST_DAYS = 7;           // pembanding: rata-rata N hari sebelumnya
// =======================
const pad = n => String(n).padStart(2, '0');
const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;

// Cron (malam) -> laporan KEMARIN yang sudah lengkap.
// Manual / test -> HARI INI sampai saat ini (data sementara).
const isTest = $execution.mode === 'test';
const nowWib = new Date(Date.now() + TZ_OFFSET_MIN * 60000);
const target = new Date(Date.UTC(nowWib.getUTCFullYear(), nowWib.getUTCMonth(), nowWib.getUTCDate() - (isTest ? 0 : 1)));
const fromMs = target.getTime() - TZ_OFFSET_MIN * 60000;   // 00:00 WIB dalam UTC
const from = new Date(fromMs).toISOString();
const to = new Date(fromMs + 86400000).toISOString();
const date = fmt(target);
const histFrom = fmt(new Date(target.getTime() - HIST_DAYS * 86400000));

// Pipeline agregasi untuk koleksi ip_access_dns.
// $convert membuat filter tanggal tetap jalan baik `timestamp` tersimpan sebagai string ISO maupun Date.
const blHits = { $sum: { $cond: [{ $eq: ['$inBlacklist', true] }, '$cnt', 0] } };
const pipeline = [
  { $addFields: {
      ts: { $convert: { input: '$timestamp', to: 'date', onError: null, onNull: null } },
      cnt: { $ifNull: ['$access_count', 1] },
      ap: { $ifNull: ['$ap_name', ''] },
  } },
  { $match: { $expr: { $and: [
      { $gte: ['$ts', { $toDate: from }] },
      { $lt: ['$ts', { $toDate: to }] },
  ] } } },
  { $facet: {
      overall: [
        { $group: { _id: null, total: { $sum: '$cnt' }, rows: { $sum: 1 }, clients: { $addToSet: '$client_ip' }, blacklist_hits: blHits } },
        { $project: { _id: 0, total: 1, rows: 1, blacklist_hits: 1, unique_clients: { $size: '$clients' } } },
      ],
      by_ap: [
        { $group: { _id: '$ap', total: { $sum: '$cnt' }, clients: { $addToSet: '$client_ip' }, blacklist_hits: blHits } },
        { $project: { total: 1, blacklist_hits: 1, unique_clients: { $size: '$clients' } } },
      ],
      by_group: [
        { $group: { _id: { group: '$group', type: '$type' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 40 },
      ],
      by_ap_group: [
        { $group: { _id: { ap: '$ap', group: '$group', type: '$type' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 600 },
      ],
      by_ap_domain: [
        { $group: { _id: { ap: '$ap', domain: '$domain', group: '$group' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 4000 },
      ],
      top_clients: [
        { $group: { _id: { client_ip: '$client_ip', ap: '$ap' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 10 },
      ],
      blacklist_events: [
        { $match: { inBlacklist: true } },
        { $group: { _id: { client_ip: '$client_ip', ap: '$ap', domain: '$domain', group: '$group' }, total: { $sum: '$cnt' } } },
        { $sort: { total: -1 } }, { $limit: 50 },
      ],
  } },
];

return [{ json: { date, partial: isTest, from, to, hist_from: histFrom, hist_days: HIST_DAYS, pipeline: JSON.stringify(pipeline) } }];

// Ubah hasil agregasi Mongo (satu dokumen $facet) menjadi dokumen statistik harian yang ringkas.
const cfg = $('Report: Date Range').first().json;
const f = ($input.first() && $input.first().json) || {};
const arr = k => (Array.isArray(f[k]) ? f[k] : []);
const num = v => (typeof v === 'number' && isFinite(v) ? v : 0);
const AP = a => (a && String(a).trim()) || 'Unknown AP';
const GRP = g => (g && String(g).trim()) || 'Unknown';

// Domain induk (registrable domain): cdn.tiktokv.com -> tiktokv.com ; a.b.co.id -> b.co.id
const SLD = new Set(['co.id', 'or.id', 'ac.id', 'go.id', 'web.id', 'sch.id', 'my.id', 'biz.id', 'mil.id', 'com.au', 'co.uk', 'com.sg', 'co.jp', 'com.br', 'co.in', 'com.my']);
const root = d => {
  const p = String(d).toLowerCase().split('.').filter(Boolean);
  if (p.length <= 2) return p.join('.');
  return SLD.has(p.slice(-2).join('.')) ? p.slice(-3).join('.') : p.slice(-2).join('.');
};

const per = new Map();
const ap = name => {
  if (!per.has(name)) per.set(name, { ap_name: name, total: 0, unique_clients: 0, blacklist_hits: 0, groups: [], domains: [] });
  return per.get(name);
};

for (const r of arr('by_ap')) {
  const e = ap(AP(r._id));
  e.total += num(r.total);
  e.unique_clients = Math.max(e.unique_clients, num(r.unique_clients));
  e.blacklist_hits += num(r.blacklist_hits);
}
for (const r of arr('by_ap_group')) {
  const id = r._id || {};
  ap(AP(id.ap)).groups.push({ group: GRP(id.group), type: id.type || 'unknown', total: num(r.total) });
}
const rolled = new Map();
for (const r of arr('by_ap_domain')) {
  const id = r._id || {};
  const a = AP(id.ap);
  const rd = root(id.domain || '');
  if (!rd) continue;
  const k = a + '||' + rd;
  const cur = rolled.get(k) || { ap: a, domain: rd, group: GRP(id.group), total: 0, top: 0 };
  const t = num(r.total);
  cur.total += t;
  if (t > cur.top) { cur.top = t; cur.group = GRP(id.group); }
  rolled.set(k, cur);
}
