const MIN_VOLUME = 50;   // abaikan entri dengan request terlalu sedikit
const PCT_UP = 30;       // dianggap naik signifikan bila >= 30% di atas rata-rata
const PCT_DOWN = 30;     // dianggap turun signifikan bila >= 30% di bawah rata-rata
const TOP_UP = 8, TOP_DOWN = 5, TOP_NEW = 5;
// ============================
const today = $('Report: Build Daily Stats').first().json;
const hist = $input.all().map(i => i.json)
  .filter(d => d && d.date && Array.isArray(d.per_ap))
  .sort((a, b) => String(a.date).localeCompare(String(b.date)));
const n = hist.length;

// key -> { value, group }
const mapOf = (doc, kind) => {
  const m = new Map();
  for (const a of doc.per_ap || []) {
    if (kind === 'ap') m.set(a.ap_name, { value: a.total || 0 });
    if (kind === 'group') for (const g of a.groups || []) {
      const k = a.ap_name + '||' + g.group;
      m.set(k, { value: ((m.get(k) || {}).value || 0) + (g.total || 0) });
    }
    if (kind === 'domain') for (const d of a.domains || []) m.set(a.ap_name + '||' + d.domain, { value: d.total || 0, group: d.group });
  }
  return m;
};

function compare(kind) {
  const tm = mapOf(today, kind);
  const hm = hist.map(d => mapOf(d, kind));
  const keys = new Set(tm.keys());
  for (const m of hm) for (const k of m.keys()) keys.add(k);
  const rows = [];
  for (const k of keys) {
    const t = (tm.get(k) || { value: 0 }).value;
    let sum = 0;
    for (const m of hm) sum += (m.get(k) || { value: 0 }).value;
    const avg = n ? sum / n : 0;
    const meta = tm.get(k) || hm.map(m => m.get(k)).find(Boolean) || {};
    const parts = kind === 'ap' ? [k, k] : k.split('||');
    rows.push({
      scope: kind, ap: parts[0], name: parts[1], group: meta.group || null,
      today: Math.round(t), baseline_avg: Math.round(avg),
      change_pct: avg > 0 ? Math.round(((t - avg) / avg) * 100) : null,
      _avg: avg,
    });
  }
  return rows;
}
const clean = r => { const { _avg, ...rest } = r; return rest; };
function classify(rows) {
  const up = rows.filter(r => r.change_pct !== null && r.change_pct >= PCT_UP && r.today >= MIN_VOLUME)
    .sort((a, b) => (b.today - b._avg) - (a.today - a._avg)).slice(0, TOP_UP).map(clean);
  const down = rows.filter(r => r.change_pct !== null && r.change_pct <= -PCT_DOWN && r._avg >= MIN_VOLUME)
    .sort((a, b) => (b._avg - b.today) - (a._avg - a.today)).slice(0, TOP_DOWN).map(clean);
  const fresh = n > 0 ? rows.filter(r => r._avg === 0 && r.today >= MIN_VOLUME)
    .sort((a, b) => b.today - a.today).slice(0, TOP_NEW).map(clean) : [];
  return { up, down, fresh };
}

const apRows = compare('ap').sort((a, b) => b.today - a.today);
const trends = {
  domain: classify(compare('domain')),
  group: classify(compare('group')),
  ap_totals: apRows.slice(0, 10).map(clean),
};

const avgOf = f => (n ? hist.reduce((s, d) => s + (d[f] || 0), 0) / n : 0);
