function toHtml(src) {
  const codes = [];
  let t = String(src).replace(/`([^`\n]+)`/g, (_, c) => { codes.push(c); return '\u0000' + (codes.length - 1) + '\u0000'; });
  t = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  for (const [k, v] of Object.entries(EMO)) t = t.split(k).join(v);
  t = t.replace(/\*([^*\n]+)\*/g, '<b>$1</b>');
  t = t.replace(/(^|[\s(])_([^_\n]+)_(?=$|[\s).,;:])/g, '$1<i>$2</i>');
  t = t.replace(/\u0000(\d+)\u0000/g, (_, i) => '<code>' + codes[Number(i)].replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</code>');
  return t;
}
return [{ json: { origin: inp.origin || 'other', severity, title, data: inp.data || null, send_slack: sendSlack, send_telegram: sendTelegram, reason,
