for (let line of String(d.tg_text).split('\n')) {
  while (line.length > LIMIT) { if (cur) { parts.push(cur); cur = ''; } parts.push(line.slice(0, LIMIT)); line = line.slice(LIMIT); }
  if ((cur + '\n' + line).length > LIMIT && cur) { parts.push(cur); cur = line; } else cur = cur ? cur + '\n' + line : line;
}
if (cur) parts.push(cur);
return parts.map((p, i) => ({ json: { chat_id: d.chat_id, tg_text: parts.length > 1 ? p + `\n<i>(${i + 1}/${parts.length})</i>` : p, idx: i + 1, total: parts.length } }));

