if (d.reason === 'empty') { out.ok = false; out.error = 'Notify: text/title kosong (' + d.origin + ')'; }
// Gagal di SEMUA kanal yang dicoba -> ok:false (ditangani di "Notify: Raise Failure"), kanal yang berhasil tidak terpengaruh
