// Pipeline agregasi sekali jalan: jendela sekarang (15 menit) + riwayat 7 hari.
// Asumsi: field `timestamp` di ip_access_dns berupa string ISO (cocok dengan insert workflow utama).
const WIN = 15 * 60000, HIST = 7 * 86400000, B = 900000;
const now = Date.now();
const curFrom = new Date(now - WIN).toISOString();
const histFrom = new Date(now - HIST).toISOString();
const bucket = { $subtract: [{ $toLong: '$tsd' }, { $mod: [{ $toLong: '$tsd' }, B] }] };
const pipeline = [
  { $match: { timestamp: { $gte: histFrom } } },
  { $addFields: { cnt: { $ifNull: ['$access_count', 1] }, ap: { $ifNull: ['$ap_name', ''] },
      tsd: { $convert: { input: '$timestamp', to: 'date', onError: null, onNull: null } } } },
  { $match: { tsd: { $ne: null } } },
  { $facet: {
    cur_ap: [{ $match: { timestamp: { $gte: curFrom } } }, { $group: { _id: '$ap', total: { $sum: '$cnt' } } }],
    cur_client: [{ $match: { timestamp: { $gte: curFrom } } }, { $group: { _id: '$client_ip', total: { $sum: '$cnt' } } }, { $sort: { total: -1 } }, { $limit: 50 }],
    cur_domains: [{ $match: { timestamp: { $gte: curFrom } } }, { $group: { _id: { domain: '$domain', client_ip: '$client_ip', ap: '$ap' }, total: { $sum: '$cnt' } } }, { $limit: 5000 }],
    hist_ap: [{ $match: { timestamp: { $lt: curFrom } } }, { $group: { _id: { ap: '$ap', b: bucket }, total: { $sum: '$cnt' } } }],
    hist_client: [{ $match: { timestamp: { $lt: curFrom } } }, { $group: { _id: { c: '$client_ip', b: bucket }, total: { $sum: '$cnt' } } },
      { $group: { _id: '$_id.c', buckets: { $sum: 1 }, total: { $sum: '$total' } } }, { $sort: { total: -1 } }, { $limit: 500 }],
    hist_domains: [{ $match: { timestamp: { $lt: curFrom } } }, { $group: { _id: '$domain' } }, { $limit: 150000 }],
  } },
];
return [{ json: { pipeline: JSON.stringify(pipeline), now } }];

// ===== Konfigurasi aturan =====
const CFG = {
  AP_MIN: 300, AP_SIGMA: 3, AP_RATIO: 2, AP_MIN_SAMPLES: 20,
  CLIENT_MIN: 500, CLIENT_RATIO: 5, CLIENT_NEW_MIN: 1000,
  DGA_ENTROPY: 3.5, DGA_MIN_LEN: 12,
  LONG_DOMAIN: 60, LONG_LABEL: 40,
  NEW_TOTAL: 40, NEW_CLIENT: 25, HIST_LIMIT: 150000,
  MAX_FINDINGS: 30,
  DOH: ['dns.google', 'dns.google.com', 'cloudflare-dns.com', 'mozilla.cloudflare-dns.com', 'one.one.one.one', 'dns.quad9.net', 'doh.opendns.com',
        'dns.adguard.com', 'dns.adguard-dns.com', 'dns.nextdns.io', 'doh.dns.sb', 'doh.cleanbrowsing.org', 'dns.cloudflare.com'],
  TTL: { ap_spike: 3600, client_spike: 3600, dga: 86400, long_domain: 86400, doh_bypass: 21600, new_domain_surge: 3600 },
  SEV: { ap_spike: 'warning', client_spike: 'warning', dga: 'warning', long_domain: 'warning', doh_bypass: 'warning', new_domain_surge: 'info' },
};
let ignore = [];
try { ignore = String($env.MSDA_ANOMALY_IGNORE_CLIENTS || '').split(',').map(s => s.trim()).filter(Boolean); } catch (e) {}  // mis. IP server n8n sendiri
// ==============================
const f = ($input.first() || {}).json || {};
const arr = k => (Array.isArray(f[k]) ? f[k] : []);
const now = Date.now();
const SLD = new Set(['co.id','or.id','ac.id','go.id','web.id','sch.id','my.id','biz.id','mil.id','desa.id','com.au','co.uk','com.sg','co.jp','com.br','co.in','com.my','co.nz','com.cn','com.hk']);
const root = d => { const p = String(d).toLowerCase().split('.').filter(Boolean); if (p.length <= 2) return p.join('.'); return SLD.has(p.slice(-2).join('.')) ? p.slice(-3).join('.') : p.slice(-2).join('.'); };
const entropy = s => { const m = {}; for (const ch of s) m[ch] = (m[ch] || 0) + 1; let h = 0; for (const k in m) { const p = m[k] / s.length; h -= p * Math.log2(p); } return h; };
const wibHour = ms => (((ms + 7 * 3600000) / 3600000) % 24 + 24) % 24;
const nowHour = wibHour(now);
const near = h => { const d = Math.abs(h - nowHour); return Math.min(d, 24 - d) <= 1; };
const fmt = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const out = [];
const add = (rule, key, line) => out.push({ rule, key: String(key), severity: CFG.SEV[rule], ttl: CFG.TTL[rule], line });

// 1) lonjakan volume per AP: bandingkan dengan jam yang sama (+-1 jam) selama 7 hari (rata-rata + 3 sigma)
const samples = new Map();
for (const r of arr('hist_ap')) { const id = r._id || {}; if (!near(wibHour(id.b))) continue; (samples.get(id.ap) || samples.set(id.ap, []).get(id.ap)).push(r.total || 0); }
for (const r of arr('cur_ap')) {
  const s = samples.get(r._id) || []; const cur = r.total || 0;
  if (s.length < CFG.AP_MIN_SAMPLES || cur < CFG.AP_MIN) continue;
  const mean = s.reduce((a, b) => a + b, 0) / s.length;
  const sd = Math.sqrt(s.reduce((a, b) => a + (b - mean) ** 2, 0) / s.length);
  if (cur > mean + CFG.AP_SIGMA * sd && cur >= CFG.AP_RATIO * mean)
    add('ap_spike', r._id || 'Unknown AP', `AP *${r._id || 'Unknown AP'}*: ${fmt(cur)} query/15 mnt (biasanya ~${fmt(mean)}, batas ${fmt(mean + CFG.AP_SIGMA * sd)})`);
}
// 2) lonjakan volume per klien: bandingkan dengan rata-rata per bucket aktif 7 hari
const hc = new Map(arr('hist_client').map(r => [r._id, r]));
for (const r of arr('cur_client')) {
  if (ignore.includes(r._id)) continue;
  const cur = r.total || 0; const h = hc.get(r._id);
  const avg = h && h.buckets ? h.total / h.buckets : 0;
  if (cur >= CFG.CLIENT_MIN && ((avg > 0 && cur >= CFG.CLIENT_RATIO * avg) || (!h && cur >= CFG.CLIENT_NEW_MIN)))
    add('client_spike', r._id, `Client \`${r._id}\`: ${fmt(cur)} query/15 mnt (biasanya ~${fmt(avg)})`);
}
// 3-6) berbasis domain
const histRoots = new Set(); for (const r of arr('hist_domains')) histRoots.add(root(r._id || ''));
const histTrunc = arr('hist_domains').length >= CFG.HIST_LIMIT;
const histKnown = histRoots.size > 0 && !histTrunc;
const dohSeen = new Map(); const dga = new Map(); const longs = new Map(); const fresh = new Map(); const freshClient = new Map();
for (const r of arr('cur_domains')) {
  const id = r._id || {}; const dm = String(id.domain || '').toLowerCase(); const cl = id.client_ip || '';
  if (!dm || ignore.includes(cl)) continue;
  const rt = root(dm); const label = rt.split('.')[0];
  const prov = CFG.DOH.find(p => dm === p || dm.endsWith('.' + p));
  if (prov) { const k = cl + '|' + prov; dohSeen.set(k, (dohSeen.get(k) || 0) + (r.total || 0)); }
  const isNew = histKnown && !histRoots.has(rt);
  if (isNew) { fresh.set(rt, cl); freshClient.set(cl, (freshClient.get(cl) || new Set()).add(rt)); }
  if (isNew && label.length >= CFG.DGA_MIN_LEN && entropy(label) >= CFG.DGA_ENTROPY && !dga.has(rt)) dga.set(rt, { cl, h: entropy(label) });
  if (isNew && (dm.length > CFG.LONG_DOMAIN || dm.split('.').some(l => l.length > CFG.LONG_LABEL)) && !longs.has(dm)) longs.set(dm, cl);
}
for (const [k, n] of dohSeen) { const [cl, prov] = k.split('|'); add('doh_bypass', k, `Client \`${cl}\` mengakses penyedia DoH/DoT \`${prov}\` (${fmt(n)}x), kemungkinan melewati DNS jaringan`); }
for (const [rt, v] of dga) add('dga', rt, `Domain mencurigakan (entropi ${v.h.toFixed(2)}) \`${rt}\` dari client \`${v.cl}\``);
for (const [dm, cl] of longs) add('long_domain', dm.slice(0, 80), `Domain sangat panjang \`${dm.slice(0, 80)}\` dari client \`${cl}\``);
if (fresh.size >= CFG.NEW_TOTAL) add('new_domain_surge', 'global', `${fresh.size} domain induk baru (belum terlihat 7 hari) dalam 15 menit`);
for (const [cl, s] of freshClient) if (s.size >= CFG.NEW_CLIENT) add('new_domain_surge', cl, `Client \`${cl}\` membuka ${s.size} domain induk baru dalam 15 menit`);

// NXDOMAIN: ip_access_dns saat ini TIDAK menyimpan rcode, jadi aturan ini belum aktif. Lihat PENYESUAIAN.md.
return out.slice(0, CFG.MAX_FINDINGS).map(x => ({ json: x }));

// Buang temuan yang sudah dikirim (kunci dedup masih ada di Redis).
const findings = $('Anomali: Evaluate Rules').all();
const gets = $input.all();
const fresh = findings.filter((f, i) => !(gets[i] && gets[i].json && gets[i].json.seen));
if (!fresh.length) return [];
const sevRank = { info: 0, warning: 1, critical: 2 };
