const NAMES = { ap_spike: 'Lonjakan volume AP', client_spike: 'Lonjakan volume client', dga: 'Domain berentropi tinggi (indikasi DGA)', long_domain: 'Domain sangat panjang',
  doh_bypass: 'Bypass DNS (DoH/DoT)', new_domain_surge: 'Lonjakan domain baru' };
const by = new Map();
