  list.slice(0, 5).forEach(x => { t += `\n\u2022 ${x.line}`; });
  if (list.length > 5) t += `\n\u2022 \u2026dan ${list.length - 5} lainnya`;
}
return [{ json: { origin: 'anomaly', severity: sev, title: '', text: t, data: { findings: fresh.map(x => ({ rule: x.json.rule, key: x.json.key, severity: x.json.severity, detail: x.json.line })) } } }];

// ===== Konfigurasi sumber feed (sakelar per sumber: enabled) =====
