const DOMAIN = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const srcs = $('Feed: Sources').all().map(i => i.json);
const res = $input.all();
const map = new Map();            // domain -> doc (duplikat dibuang)
const stats = [];
res.forEach((r, i) => {
  const s = srcs[i]; const j = r.json || {};
  const text = typeof j.data === 'string' ? j.data : (typeof j === 'string' ? j : '');
  if (!s || j.error || !text) { stats.push(`${s ? s.id : '?'}: gagal`); return; }
  let n = 0;
  for (let line of text.split(/\r?\n/)) {
    line = line.replace(/#.*$/, '').trim().toLowerCase();
    if (!line) continue;
    let dom = line;
    if (s.format === 'hosts') { const p = line.split(/\s+/); if (p.length < 2) continue; dom = p[1]; }
    dom = dom.replace(/\.$/, '');
    if (['localhost', 'localhost.localdomain', 'local', 'broadcasthost', '0.0.0.0'].includes(dom)) continue;
    if (!DOMAIN.test(dom)) continue;
    if (map.has(dom)) continue;
    if (n >= s.max) break;
    n++;
    map.set(dom, { domain: dom, group: s.group, type: s.type, source: 'feed', feed: s.id, is_active: true,
      description: 'Feed ' + s.id, updated_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + s.ttl_days * 86400000).toISOString() });
  }
  stats.push(`${s.id}: ${n}`);
});
const docs = [...map.values()];
return [{ json: { docs, stats, query: JSON.stringify({ domain: { $in: docs.map(d => d.domain) }, $or: [{ source: { $ne: 'feed' } }, { is_active: false }] }) } }];

// Jangan timpa entri manual (source kosong/manual/telegram/...) dan jangan aktifkan lagi entri feed yang dinonaktifkan admin.
