// Dijalankan Senin 00:10 WIB: minggu lalu (Sen-Min) vs minggu sebelumnya. Manual test: 7 hari terakhir s.d. kemarin.
const OFF = 7 * 3600000;
const pad = n => String(n).padStart(2, '0');
const fmt = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
const nowW = new Date(Date.now() + OFF);
const today = new Date(Date.UTC(nowW.getUTCFullYear(), nowW.getUTCMonth(), nowW.getUTCDate()));
const days = k => Array.from({ length: 7 }, (_, i) => fmt(new Date(today.getTime() - (k * 7 - i) * 86400000)));
const cur = days(1), prev = days(2);
// nomor minggu ISO dari tanggal akhir minggu
const e = new Date(today.getTime() - 86400000); const t = new Date(Date.UTC(e.getUTCFullYear(), e.getUTCMonth(), e.getUTCDate()));
t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
const ys = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
const wk = Math.ceil(((t - ys) / 86400000 + 1) / 7);
const key = `${t.getUTCFullYear()}-W${pad(wk)}`;
return [{ json: { cur, prev, key, week_start: cur[0], week_end: cur[6], query: JSON.stringify({ date: { $in: [...cur, ...prev] }, period: { $ne: 'weekly' } }) } }];

const cfg = $('Mingguan: Weekly: Date Range').first().json;
const docs = $input.all().map(i => i.json).filter(d => d && d.date && Array.isArray(d.per_ap));
const inCur = new Set(cfg.cur), inPrev = new Set(cfg.prev);
const cur = docs.filter(d => inCur.has(d.date)), prev = docs.filter(d => inPrev.has(d.date));
const sum = (a, k) => a.reduce((s, d) => s + (d[k] || 0), 0);
const num = x => (typeof x === 'number' && isFinite(x) ? x : 0);
const pct = (a, b) => (b > 0 ? Math.round(((a - b) / b) * 100) : null);
const fmt = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const signed = p => (p === null ? 'baru' : (p >= 0 ? '+' : '') + p + '%');
if (!cur.length) return [{ json: { has_data: false, key: cfg.key, week_start: cfg.week_start, week_end: cfg.week_end,
  slack_text: `:warning: *Laporan Mingguan MSDA ${cfg.week_start} s.d. ${cfg.week_end}*\nTidak ada data harian (dns_daily_stats) pada periode ini.` } }];

const agg = (a, kind) => {
  const m = new Map();
  for (const d of a) for (const ap of d.per_ap || []) {
    if (kind === 'ap') m.set(ap.ap_name, (m.get(ap.ap_name) || 0) + num(ap.total));
    if (kind === 'group') for (const g of ap.groups || []) m.set(g.group, (m.get(g.group) || 0) + num(g.total));
    if (kind === 'domain') for (const x of ap.domains || []) m.set(x.domain, (m.get(x.domain) || 0) + num(x.total));
  } return m;
};
const cmp = kind => {
  const c = agg(cur, kind), p = agg(prev, kind);
  return [...new Set([...c.keys(), ...p.keys()])].map(k => ({ name: k, this_week: c.get(k) || 0, last_week: p.get(k) || 0, change_pct: pct(c.get(k) || 0, p.get(k) || 0) }))
    .sort((a, b) => b.this_week - a.this_week);
};
const totals = { requests: sum(cur, 'total_requests'), prev_requests: sum(prev, 'total_requests'), blacklist_hits: sum(cur, 'blacklist_hits'), prev_blacklist_hits: sum(prev, 'blacklist_hits'),
  peak_unique_clients: Math.max(0, ...cur.map(d => num(d.unique_clients))), prev_peak_unique_clients: Math.max(0, ...prev.map(d => num(d.unique_clients))), days_cur: cur.length, days_prev: prev.length };
totals.change_pct = pct(totals.requests, totals.prev_requests);
const byAp = cmp('ap').slice(0, 10), byGroup = cmp('group').slice(0, 12), byDomain = cmp('domain').slice(0, 15);
const rising = cmp('domain').filter(r => r.change_pct !== null && r.change_pct >= 50 && r.this_week >= 200).sort((a, b) => (b.this_week - b.last_week) - (a.this_week - a.last_week)).slice(0, 8);
const fresh = cmp('domain').filter(r => r.last_week === 0 && r.this_week >= 200).slice(0, 8);
const trends = { totals, by_ap: byAp, by_group: byGroup, top_domains: byDomain, rising, fresh };
const prompt = 'Kamu analis keamanan jaringan untuk sistem MSDA (monitoring DNS). Bandingkan minggu ' + cfg.week_start + ' s.d. ' + cfg.week_end + ' dengan minggu sebelumnya. Data (JSON): ' + JSON.stringify(trends) +
  '. Balas HANYA JSON objek valid: {"summary": "2-3 kalimat", "insights": ["maks 6 poin tren"], "recommendations": ["maks 3 saran"]}. Bahasa Indonesia, singkat, jangan mengarang angka yang tidak ada di data.';
return [{ json: { has_data: true, key: cfg.key, week_start: cfg.week_start, week_end: cfg.week_end, trends, totals, fmt_total: fmt(totals.requests),
  ai_request: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { maxOutputTokens: 4096, thinkingConfig: { thinkingLevel: 'low' }, responseMimeType: 'application/json' } } } }];

const ctx = $('Mingguan: Weekly: Compute').first().json;
const resp = ($input.first() && $input.first().json) || {};
let ai = null;
try {
  const parts = (((resp.candidates || [])[0] || {}).content || {}).parts || [];
  const text = parts.filter(p => !p.thought && typeof p.text === 'string').map(p => p.text).join('');
  const p = JSON.parse(text.replace(/```json|```/g, '').trim());
  if (p && typeof p === 'object' && !Array.isArray(p)) ai = p;
} catch (e) {}
const strs = v => (Array.isArray(v) ? v.filter(x => typeof x === 'string' && x.trim()).map(x => x.trim()) : []);
const fmt = n => String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const signed = p => (p === null || p === undefined ? 'baru' : (p >= 0 ? '+' : '') + p + '%');
const T = ctx.totals;
let insights = ai ? strs(ai.insights).slice(0, 6) : [];
if (!insights.length) insights = [
  ...ctx.trends.rising.slice(0, 4).map(r => `\`${r.name}\` naik ${signed(r.change_pct)} (${fmt(r.this_week)} vs ${fmt(r.last_week)})`),
  ...ctx.trends.fresh.slice(0, 2).map(r => `\`${r.name}\` baru muncul (${fmt(r.this_week)} request)`)];
let t = `:bar_chart: *Laporan Mingguan MSDA \u2014 ${ctx.week_start} s.d. ${ctx.week_end}*\n`;
t += `Total *${fmt(T.requests)}* request (${signed(T.change_pct)} vs minggu lalu) | puncak *${fmt(T.peak_unique_clients)}* client/hari | *${fmt(T.blacklist_hits)}* akses blacklist (minggu lalu ${fmt(T.prev_blacklist_hits)})`;
if (T.days_cur < 7) t += `\n_Data hanya ${T.days_cur} dari 7 hari._`;
if (ai && typeof ai.summary === 'string' && ai.summary.trim()) t += `\n\n${ai.summary.trim()}`;
t += '\n\n*Insight Tren*' + (insights.length ? '\n' + insights.map(x => `\u2022 ${x}`).join('\n') : '\n\u2022 Tidak ada perubahan signifikan.');
const apl = ctx.trends.by_ap.slice(0, 6).map(a => `\u2022 *${a.name}*: ${fmt(a.this_week)} (${signed(a.change_pct)})`);
if (apl.length) t += '\n\n*Per Access Point*\n' + apl.join('\n');
const recs = ai ? strs(ai.recommendations).slice(0, 3) : [];
if (recs.length) t += '\n\n*Saran*\n' + recs.map(x => `\u2022 ${x}`).join('\n');
t += '\n\n_' + (ai ? 'Dianalisis AI dari dns_daily_stats' : 'Analisis AI tidak tersedia, ini ringkasan otomatis') + '_';
return [{ json: { date: ctx.key, period: 'weekly', week_start: ctx.week_start, week_end: ctx.week_end, partial: T.days_cur < 7,
  generated_at: new Date().toISOString(), model: resp.modelVersion || null, ai_ok: !!ai, history_days: T.days_prev,
  ai, summary: T, trends: ctx.trends, slack_text: t, severity: 'info', text: t } }];

// Hanya terima dari ID pengguna yang ada di daftar putih (env MSDA_TELEGRAM_ALLOWED_IDS, dipisah koma).
const u = $input.first().json || {};
const cb = u.callback_query || null;
const msg = cb ? (cb.message || {}) : (u.message || {});
const from = cb ? cb.from : (u.message || {}).from;
if (!from) return [{ json: { allowed: false } }];
let allowed = [], approvers = [];
try { allowed = String($env.MSDA_TELEGRAM_ALLOWED_IDS || '').split(',').map(s => s.trim()).filter(Boolean); } catch (e) {}
try { approvers = String($env.MSDA_TELEGRAM_APPROVER_IDS || '').split(',').map(s => s.trim()).filter(Boolean); } catch (e) {}
const ok = allowed.includes(String(from.id));
let kind = 'text', cmd = '', arg = '';
if (cb) { kind = 'callback'; const m = String(cb.data || '').match(/^(blk|mt):(.+)$/); cmd = m ? m[1] : String(cb.data || ''); arg = m ? m[2] : ''; }
else {
  const m = String((u.message || {}).text || '').trim().match(/^\/([a-z_]+)(?:@\w+)?(?:\s+(.*))?$/i);
  if (m) { cmd = m[1].toLowerCase(); arg = (m[2] || '').trim().split(/\s+/)[0] || ''; }
}
return [{ json: { allowed: ok, kind, cmd, arg: arg.toLowerCase(), chat_id: (msg.chat || {}).id || from.id, from_id: String(from.id),
  from_name: from.username ? '@' + from.username : [from.first_name, from.last_name].filter(Boolean).join(' '),
  callback_id: cb ? cb.id : '', is_approver: approvers.includes(String(from.id)) } }];

// Validasi domain ketat SEBELUM menyentuh Mongo. Input bebas tidak pernah dijalankan sebagai query.
const a = $('TG: Auth & Parse').first().json;
const cnt = Number(Object.values(($input.first() || {}).json || {})[0] || 0);
const DOMAIN = /^(?=.{4,55}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;   // maks 55 karakter (batas callback_data Telegram 64 byte)
let enforce = false; try { enforce = String($env.MSDA_ENFORCE_ENABLED || '') === 'true'; } catch (e) {}
const reply = (text, extra = {}) => [{ json: { route: 'reply', reply: text, chat_id: a.chat_id, ...extra } }];
if (cnt > 10) return reply('Terlalu banyak perintah, coba lagi sebentar lagi.');
const HELP = '<b>Perintah MSDA</b>\n/status \u2013 ringkasan 1 jam terakhir\n/top \u2013 10 domain teratas 24 jam\n/block &lt;domain&gt; \u2013 blokir (dengan konfirmasi)\n/unblock &lt;domain&gt; \u2013 nonaktifkan entri blacklist';
if (a.kind === 'text') {
  if (a.cmd === 'status') return [{ json: { route: 'status', chat_id: a.chat_id } }];
  if (a.cmd === 'top') return [{ json: { route: 'top', chat_id: a.chat_id } }];
  if (a.cmd === 'block' || a.cmd === 'unblock') {
    if (!DOMAIN.test(a.arg)) return reply('Domain tidak valid. Contoh: <code>/' + a.cmd + ' contoh.com</code>');
    if (a.cmd === 'block') return [{ json: { route: 'block_confirm', chat_id: a.chat_id, domain: a.arg, cb_yes: 'blk:' + a.arg } }];
    return [{ json: { route: 'unblock_do', chat_id: a.chat_id, domain: a.arg, by: a.from_name + ' (' + a.from_id + ')' } }];
  }
  return reply(HELP);
}
if (a.cmd === 'cancel') return reply('Dibatalkan.');
if (a.cmd === 'blk') {
  if (!DOMAIN.test(a.arg)) return reply('Domain tidak valid.');
  return [{ json: { route: 'block_do', chat_id: a.chat_id, domain: a.arg, by: a.from_name + ' (' + a.from_id + ')', offer_enforce: enforce } }];
}
if (a.cmd === 'mt') {
  if (!enforce) return reply('Penegakan ke MikroTik belum diaktifkan.');
  if (!a.is_approver) return reply('Anda bukan approver penegakan MikroTik.');
  if (!DOMAIN.test(a.arg)) return reply('Domain tidak valid.');
  return [{ json: { route: 'enforce', chat_id: a.chat_id, domain: a.arg, by: a.from_name + ' (' + a.from_id + ')' } }];
}
return reply(HELP);

const r = (($input.first() || {}).json) || {};
const n = x => String(Math.round(x || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
return [{ json: { chat_id: $('TG: Route').first().json.chat_id, reply: `<b>Status 1 jam terakhir</b>
Request: <b>${n(r.total)}</b>
Client unik: <b>${n(r.clients)}</b>
Akses blacklist: <b>${n(r.blacklist)}</b>` + (r.total ? '' : '
<i>Tidak ada data.</i>') } }];

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map(i => i.json).filter(x => x && x._id);
const t = rows.length ? rows.map((x, i) => `${i + 1}. <code>${esc(x._id)}</code> \u2013 ${x.total}`).join('\n') : '<i>Tidak ada data.</i>';
return [{ json: { chat_id: $('TG: Route').first().json.chat_id, reply: '<b>Top 10 domain (24 jam)</b>\n' + t } }];

const r = $('TG: Route').first().json;
const text = r.route === 'block_do' ? `\u2705 <code>${r.domain}</code> masuk blacklist (diminta ${r.by}).` : `\u2705 <code>${r.domain}</code> dinonaktifkan dari blacklist.`;
return [{ json: { chat_id: r.chat_id, reply: text, offer: r.route === 'block_do' && r.offer_enforce, domain: r.domain } }];

const r = $('TG: Route').first().json; const ro = $input.first().json || {};
const ok = !ro.error && (ro['.id'] || ro.name);          // jika node RouterOS dinonaktifkan, tidak ada '.id' => dilaporkan gagal
return [{ json: { chat_id: r.chat_id, reply: ok ? `\u2705 <code>${r.domain}</code> diterapkan ke MikroTik.` : `\u274C Gagal menerapkan <code>${r.domain}</code> ke MikroTik (fitur nonaktif atau router tidak merespons).` } }];

// Pesan error ringkas. JANGAN sertakan payload/data eksekusi.
const e = $input.first().json || {};
const wfn = (e.workflow && e.workflow.name) || 'workflow tidak dikenal';
const ex = e.execution || {};
const clean = s => String(s || '').replace(/[A-Za-z0-9_\-]{32,}/g, '[disamarkan]').replace(/\s+/g, ' ').slice(0, 300);
const wib = new Date(Date.now() + 7 * 3600000).toISOString().replace('T', ' ').slice(0, 19) + ' WIB';
let t = `:rotating_light: *Workflow gagal*\nWorkflow: *${wfn}*\n`;
t += `Node: \`${ex.lastNodeExecuted || '-'}\`\n`;
t += `Pesan: ${clean(ex.error && ex.error.message)}\n`;
t += `Waktu: ${wib}`;
if (ex.url) t += `\nEksekusi: ${ex.url}`;
return [{ json: { severity: 'critical', title: '', text: t, data: { workflow: wfn, execution_id: ex.id || null } } }];

// Monitor AdGuard Home. n8n TIDAK memanggil AdGuard; hanya membaca status ringkas dari backend MSDA.
// Satu alert per gangguan (flag Redis adguard_down, TTL 24 jam) + pesan pemulihan.
// Penting bila MikroTik memakai DNS cadangan (gagal-buka): tanpa alert ini pemblokiran bisa mati tanpa ada yang tahu.
const st = ($('AdGuard: Status backend').first() || {}).json || {};
const flag = !!((($input.first() || {}).json || {}).flag);
// Fitur nonaktif (enabled:false) atau backend tidak terjangkau (tidak ada field enabled) => tidak ada tindakan.
if (st.enabled !== true) return [{ json: { action: 'none', reason: 'enforcement nonaktif atau backend tidak terjangkau' } }];

const TEXT = {
  unreachable: 'AdGuard Home tidak dapat dihubungi; pemblokiran DNS mungkin tidak aktif.',
  protection_off: 'Proteksi AdGuard dimatikan; tidak ada domain yang diblokir.',
  sync_error: 'Sinkronisasi aturan terakhir gagal.',
  sync_stale: 'Aturan sudah lama tidak disinkronkan.',
  never_synced: 'Aturan belum pernah disinkronkan.',
};
const problems = Array.isArray(st.problems) ? st.problems : [];
const unhealthy = st.healthy === false || problems.length > 0;
const wib = s => s ? new Date(new Date(s).getTime() + 7 * 3600000).toISOString().replace('T', ' ').slice(0, 19) + ' WIB' : 'belum pernah';
const info = `Aturan aktif: ${st.rule_count ?? 0} | Sinkronisasi terakhir: ${wib(st.last_sync_at)}`;

if (unhealthy && !flag) {
  const critical = problems.includes('unreachable') || problems.includes('protection_off');
  return [{ json: { action: 'down', origin: 'adguard_down', severity: critical ? 'critical' : 'warning', text:
    `:rotating_light: *AdGuard Home bermasalah*\n` + (problems.length ? problems.map(p => '\u2022 ' + (TEXT[p] || p)).join('\n') : '\u2022 Status tidak sehat.') +
    `\n${info}\nDomain bermode Block DNS mungkin tidak diblokir sampai pulih.` } }];
}
if (!unhealthy && flag) {
  return [{ json: { action: 'recover', origin: 'adguard_up', severity: 'warning', text:
    `:white_check_mark: *AdGuard Home pulih*\nPemblokiran DNS kembali normal.\n${info}` } }];
}
return [{ json: { action: 'none' } }];
